head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25000.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_companyInfo.get("comNm")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_companyInfo.get("ceoNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_companyInfo.get("corpTelNo")); } },
        { childId: "__rb4", attr: "label", fn: function () { return "http://" + String(dma_companyInfo.get("hpage")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(dma_companyInfo.get("engIrInfo")); } },
        { childId: "__rb6", attr: "label", fn: function () { return String(dma_companyInfo.get("majProdNm")); } },
        { childId: "__rb7", attr: "label", fn: function () { return String(dma_companyInfo.get("empCnt")) + " 명"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dma_companyInfo.get("zipcd")) + " " + String(dma_companyInfo.get("addr")) + " " + String(dma_companyInfo.get("dtlAddr")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_GoDsclInsert_onclick
 * @description btn_GoDsclInsert 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoDsclInsert_onclick = async function(e){
    try {
        await scwin.goDsclInsert('대표이사(대표집행임원) 변경(안내공시)');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.btn_GoDsclInsert_onclick' }); }
};

/**
 * @method
 * @name btn_GoDsclInsert_2_onclick
 * @description btn_GoDsclInsert_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoDsclInsert_2_onclick = async function(e){
    try {
        await scwin.goDsclInsert('본점소재지변경')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.btn_GoDsclInsert_2_onclick' }); }
};

/**
 * @method
 * @name ipt_corpTelNoCk_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_corpTelNoCk_onclick = async function(e){
    try {
        await scwin.activeInput('corpTelNo')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.ipt_corpTelNoCk_onclick' }); }
};

/**
 * @method
 * @name ipt_hpageCk_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_hpageCk_onclick = async function(e){
    try {
        await scwin.activeInput('hpage')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.ipt_hpageCk_onclick' }); }
};

/**
 * @method
 * @name ipt_engIrInfoCk_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_engIrInfoCk_onclick = async function(e){
    try {
        await scwin.activeInput('engIrInfo')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.ipt_engIrInfoCk_onclick' }); }
};

/**
 * @method
 * @name ipt_majProdNmCk_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_majProdNmCk_onclick = async function(e){
    try {
        await scwin.activeInput('majProdNm')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.ipt_majProdNmCk_onclick' }); }
};

/**
 * @method
 * @name ipt_empCntCk_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_empCntCk_onclick = async function(e){
    try {
        await scwin.activeInput('empCnt')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.ipt_empCntCk_onclick' }); }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25000.btn_Save_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoDsclInsert
 * @description Go Dscl Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoDsclInsert = async function () {
    const sbmOptions = {
        id: "tx_fn_GoDsclInsert",
        method: "post",
        action: "/submission/searchDisclosureForm.do",
        ref: "dma_GoDsclInsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Save
 * @description Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Save = async function () {
    try { return await $c.data.downFile("/account/corporationReport.do", "", ($c.util.getComponent("dma_SaveReq") ? $c.util.getComponent("dma_SaveReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goDsclInsert
 * @description go Dscl Insert 처리
 * @param {String} formKorNm formKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goDsclInsert = async function (formKorNm) {
    $c.util.getComponent('dma_GoDsclInsertReq').set('formKorNm', formKorNm);
    await scwin.tx_fn_GoDsclInsert();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    const frm = $c.util.getComponent('corpForm');
    const isCorpTelNoCk = (String($c.util.getComponent('ipt_corpTelNoCk').getValue() || "") !== "");
    const isHpageCk = (String($c.util.getComponent('ipt_hpageCk').getValue() || "") !== "");
    const isEngIrInfoCk = (String($c.util.getComponent('ipt_engIrInfoCk').getValue() || "") !== "");
    const isMajProdNmCk = (String($c.util.getComponent('ipt_majProdNmCk').getValue() || "") !== "");
    const isEmpCntCk = (String($c.util.getComponent('ipt_empCntCk').getValue() || "") !== "");
    if (!(isCorpTelNoCk || isHpageCk || isEngIrInfoCk || isMajProdNmCk || isEmpCntCk)) {
        await $c.win.alert('변경사항이 없습니다.');
        return;
    }
    if (isCorpTelNoCk) {
        if (await scwin.checkRequired($c.util.getComponent('ipt_corpTelNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_corpTelNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_corpTelNo3'))) {
            return;
        }
        if (!(scwin.isNumberInput($c.util.getComponent('ipt_corpTelNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_corpTelNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_corpTelNo3')))) {
            await $c.win.alert('대표전화번호는 숫자만 입력하세요');
            return;
        }
        const corpTelNoVal = $c.util.getComponent('ipt_corpTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_corpTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_corpTelNo3').getValue();
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', corpTelNoVal);
    } else {
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', "");
    }
    if (isHpageCk) {
        if (await scwin.checkRequired($c.util.getComponent('ipt_hpage'))) {
            return;
        }
    } else {
        $c.util.getComponent("ipt_hpage").setValue("");
    }
    if (isEngIrInfoCk) {
        if (await scwin.checkRequired($c.util.getComponent('ipt_engIrInfo'))) {
            return;
        }
    } else {
        $c.util.getComponent("ipt_engIrInfo").setValue("");
    }
    if (isMajProdNmCk) {
        if (await scwin.checkRequired($c.util.getComponent('ipt_majProdNm'))) {
            return;
        }
    } else {
        $c.util.getComponent("ipt_majProdNm").setValue("");
    }
    if (isEmpCntCk) {
        if (await scwin.checkRequired($c.util.getComponent('ipt_empCnt'))) {
            return;
        }
        if (!scwin.isNumberInput($c.util.getComponent('ipt_empCnt'))) {
            await $c.win.alert('종업원수는 숫자만 입력하세요.');
            return;
        }
    } else {
        $c.util.getComponent("ipt_empCnt").setValue("");
    }
    $c.util.getComponent('dma_GoDsclInsertReq').set('method', 'modifyCorporationReport');
    frm.action = 'corporationReport.do';
    await scwin.tx_fn_Save();
};

/**
 * @method
 * @name activeInput
 * @description active Input 처리
 * @param {*} _target _target
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.activeInput = async function (_target) {
    const frm = $c.util.getComponent('corpForm');
    if (_target === 'corpTelNo') {
        if ((String($c.util.getComponent('ipt_corpTelNoCk').getValue() || "") !== "")) {
            $c.util.getComponent('ipt_corpTelNo1').readOnly = false;
            $c.util.getComponent('ipt_corpTelNo2').readOnly = false;
            $c.util.getComponent('ipt_corpTelNo3').readOnly = false;
        } else {
            $c.util.getComponent('ipt_corpTelNo1').readOnly = true;
            $c.util.getComponent('ipt_corpTelNo2').readOnly = true;
            $c.util.getComponent('ipt_corpTelNo3').readOnly = true;
        }
    } else {
        if (_target === 'hpage') {
            if ((String($c.util.getComponent('ipt_hpageCk').getValue() || "") !== "")) {
                $c.util.getComponent('ipt_hpage').readOnly = false;
            } else {
                $c.util.getComponent('ipt_hpage').readOnly = true;
            }
        } else {
            if (_target === 'engIrInfo') {
                if ((String($c.util.getComponent('ipt_engIrInfoCk').getValue() || "") !== "")) {
                    $c.util.getComponent('ipt_engIrInfo').readOnly = false;
                } else {
                    $c.util.getComponent('ipt_engIrInfo').readOnly = true;
                }
            } else {
                if (_target === 'majProdNm') {
                    if ((String($c.util.getComponent('ipt_majProdNmCk').getValue() || "") !== "")) {
                        $c.util.getComponent('ipt_majProdNm').readOnly = false;
                    } else {
                        $c.util.getComponent('ipt_majProdNm').readOnly = true;
                    }
                } else {
                    if (_target === 'empCnt') {
                        if ((String($c.util.getComponent('ipt_empCntCk').getValue() || "") !== "")) {
                            $c.util.getComponent('ipt_empCnt').readOnly = false;
                            await $c.win.alert('종업원수는 담당자 승인 후 변경됩니다.');
                        } else {
                            $c.util.getComponent('ipt_empCnt').readOnly = true;
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function () {
    document.location.href = "/";
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
